package com.fiap.hackgov.tools.internal.controllers;import com.fiap.hackgov.cityhall_management.internal.entities.Employee;import com.fiap.hackgov.tools.internal.services.ToolConfigurationService;import lombok.RequiredArgsConstructor;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/tools") @RequiredArgsConstructor public class ToolConfigurationController{private final ToolConfigurationService service;@GetMapping public List<ToolConfigurationService.Response> list(@AuthenticationPrincipal Employee e){return service.list(e);}@PatchMapping("/{slug}")public ToolConfigurationService.Response update(@PathVariable String slug,@RequestBody ToolConfigurationService.Update r,@AuthenticationPrincipal Employee e){return service.update(slug,r,e);}@PostMapping("/{slug}/favorite")public ToolConfigurationService.Favorite favorite(@PathVariable String slug,@AuthenticationPrincipal Employee e){return service.favorite(slug,e);}}
